package main

import (
	"fmt"
	"github.com/prest/prest/v2/middlewares"
	jose "gopkg.in/square/go-jose.v2"
)

func main() {
	// Test that our jwtAlgo function works correctly
	algorithms := []string{"HS256", "HS384", "HS512", "RS256", "RS384", "RS512", "ES256", "ES384", "ES512", "PS256", "PS384", "PS512", "EdDSA"}

	for _, algo := range algorithms {
		result := middlewares.JwtAlgo(algo)
		fmt.Printf("Algorithm %s -> %s\n", algo, result)
	}

	// Test default case
	defaultResult := middlewares.JwtAlgo("UNKNOWN")
	fmt.Printf("Unknown algorithm -> %s (should be HS256)\n", defaultResult)

	// Verify HS256 is the default
	if defaultResult == jose.HS256 {
		fmt.Println("✓ Default algorithm correctly set to HS256")
	} else {
		fmt.Println("✗ Default algorithm is not HS256")
	}
}
EOF
